-- Drill hints (S45): two per drill, from supabase/content/drill-hints.json. Safe to re-run.
do $codeyhints$ begin
update public.content_exercises set hints = '["Optional binding runs a block only when the optional has a value.", "It''s the same keyword you''d use for any condition; Swift 5.7+ lets you write just `___ let name` without `= name`."]'::jsonb where id = 'ex-swift-if-let';
update public.content_exercises set hints = '["This is an early exit: check the condition up front and leave if it fails.", "Blank 1 is the keyword for an early-exit check; blank 2 is the word that introduces the block that runs when the check fails."]'::jsonb where id = 'ex-swift-guard';
update public.content_exercises set hints = '["You want a new array with every element transformed.", "The higher-order function that transforms each element and returns an array of the results."]'::jsonb where id = 'ex-swift-map';
update public.content_exercises set hints = '["Struct methods can''t change stored properties by default.", "Mark the method with the keyword that lets a value-type method modify `self`."]'::jsonb where id = 'ex-swift-mutating';
update public.content_exercises set hints = '["Every Python function starts with a keyword.", "It''s short for \"define\"."]'::jsonb where id = 'ex-python-def';
update public.content_exercises set hints = '["A list comprehension reads like: value, loop, optional filter.", "Blank 1 starts the loop over `numbers`; blank 2 starts the filter condition."]'::jsonb where id = 'ex-python-comprehension';
update public.content_exercises set hints = '["Reading a missing key with `counts[word]` raises `KeyError`.", "Use the dict method that returns a default value when the key isn''t there."]'::jsonb where id = 'ex-python-dict-get';
update public.content_exercises set hints = '["The loop must still run when the range has one item left.", "Blank 1 compares `low` and `high` so equal still loops; blank 2 moves past `mid`, since `mid` was already checked."]'::jsonb where id = 'ex-alg-binary-search';
update public.content_exercises set hints = '["Recursion needs a stopping value and a smaller subproblem.", "0! and 1! are both the same small number; the recursive call works on the number just below `n`."]'::jsonb where id = 'ex-alg-factorial';
update public.content_exercises set hints = '["A stack adds and removes at the same end: last in, first out.", "Array methods: one adds at the end, the other removes the last element and returns it as an optional."]'::jsonb where id = 'ex-ds-stack';
update public.content_exercises set hints = '["A queue is first in, first out: take from the front.", "`deque` has a pop method for the left end."]'::jsonb where id = 'ex-ds-queue';
update public.content_exercises set hints = '["Java has a keyword for \"is a subclass of\".", "It''s the keyword for class inheritance, not the one for interfaces."]'::jsonb where id = 'ex-oop-inheritance';
update public.content_exercises set hints = '["SQL filters rows with a clause after `FROM`.", "The clause that keeps only rows matching a condition."]'::jsonb where id = 'ex-db-where';
update public.content_exercises set hints = '["You need to sort the rows, then keep only the first few.", "Blank 1 is the two-word sorting clause; blank 2 caps the number of rows returned."]'::jsonb where id = 'ex-db-order-limit';
update public.content_exercises set hints = '["Never paste user input into SQL; pass it as a parameter instead.", "sqlite3 uses a single-character placeholder for each value in the tuple."]'::jsonb where id = 'ex-db-placeholder';
update public.content_exercises set hints = '["`COUNT(*)` per customer means collapsing rows into one group per customer.", "The two-word clause that groups rows by a column''s value."]'::jsonb where id = 'ex-db-group-by';
update public.content_exercises set hints = '["TCP is a reliable, connection-based byte stream.", "Choose the socket type constant for streams (UDP would be datagrams)."]'::jsonb where id = 'ex-net-tcp-socket';
update public.content_exercises set hints = '["The response object knows the HTTP status code the server sent.", "Read it as an attribute named for what it is (200, 404, …)."]'::jsonb where id = 'ex-net-http-status';
update public.content_exercises set hints = '["Every 2xx code is from 200 up to, but not including, 300.", "Write a Swift range: half-open `..<` or closed `...`."]'::jsonb where id = 'ex-net-success-range';
update public.content_exercises set hints = '["A thread does nothing until it''s started, and the main thread doesn''t wait unless told to.", "Blank 1 begins running `work`; blank 2 blocks until the thread finishes."]'::jsonb where id = 'ex-os-thread-join';
update public.content_exercises set hints = '["Only one thread at a time should run `count += 1`.", "Use the statement that acquires the lock and releases it automatically at the end of the block."]'::jsonb where id = 'ex-os-lock';
update public.content_exercises set hints = '["`async let` starts both tasks; you still have to wait for their results.", "The keyword that suspends until async values are ready (alongside `try`)."]'::jsonb where id = 'ex-os-async-let';
update public.content_exercises set hints = '["A struct adopts a protocol by listing it after a colon.", "Write the name of the protocol it should conform to."]'::jsonb where id = 'ex-oop-protocol';
update public.content_exercises set hints = '["Java has an annotation that says \"this replaces the parent''s method\".", "It starts with `@`, and the compiler checks the parent really has that method."]'::jsonb where id = 'ex-oop-override';
update public.content_exercises set hints = '["Python calls a special method when an object is created.", "The constructor''s name has two underscores on each side."]'::jsonb where id = 'ex-oop-init';
update public.content_exercises set hints = '["Java''s enhanced for loop reads \"for each score in scores\".", "One punctuation character separates the variable from the collection."]'::jsonb where id = 'ex-java-for-each';
update public.content_exercises set hints = '["A class promises to provide an interface''s methods.", "For interfaces Java uses a different keyword than `extends`."]'::jsonb where id = 'ex-java-implements';
update public.content_exercises set hints = '["`try` needs a handler for the exception it might throw.", "The block that handles a specific exception type after `try`."]'::jsonb where id = 'ex-java-catch';
update public.content_exercises set hints = '["`counts.get(word)` returns `null` for a new word, and `null + 1` crashes.", "Use the `Map` method that returns a fallback value when the key is missing."]'::jsonb where id = 'ex-java-get-or-default';
update public.content_exercises set hints = '["By default C++ passes copies, so changing them doesn''t affect the caller.", "Make each parameter a reference with the same symbol in both places."]'::jsonb where id = 'ex-cpp-swap-ref';
update public.content_exercises set hints = '["You want to add an element to the end of the vector.", "The `std::vector` method that appends (or constructs in place) at the back."]'::jsonb where id = 'ex-cpp-push-back';
update public.content_exercises set hints = '["A smart pointer that owns its object frees it when it goes out of scope.", "Use the factory function for `std::unique_ptr`."]'::jsonb where id = 'ex-cpp-unique-ptr';
update public.content_exercises set hints = '["`auto name` would copy each string.", "Bind each element as a reference you can''t modify (`const` plus `&`)."]'::jsonb where id = 'ex-cpp-const-ref';
update public.content_exercises set hints = '["Git has a staging area between your files and a commit.", "The git command that stages changes; `.` means everything."]'::jsonb where id = 'ex-git-stage';
update public.content_exercises set hints = '["Staged changes are saved into history by one command.", "The git command that records a snapshot; `-m` gives its message."]'::jsonb where id = 'ex-git-commit';
update public.content_exercises set hints = '["`git switch` changes branches; a flag makes it create the branch first.", "The short flag is one letter (the long form is `--create`)."]'::jsonb where id = 'ex-git-branch';
update public.content_exercises set hints = '["Building SQL with string concatenation allows SQL injection.", "Use the driver''s placeholder and pass `email` in the tuple."]'::jsonb where id = 'ex-sec-param-query';
update public.content_exercises set hints = '["Characters like `<` and `>` in user input can become HTML tags.", "The `html` module function that turns them into entities like `&lt;`."]'::jsonb where id = 'ex-sec-escape-html';
update public.content_exercises set hints = '["`==` can stop at the first different character, which leaks timing.", "`hmac` has a constant-time comparison function."]'::jsonb where id = 'ex-sec-compare-digest';
update public.content_exercises set hints = '["A salt must be random and unpredictable.", "Use the `os` function that returns cryptographically secure random bytes."]'::jsonb where id = 'ex-sec-hash-password';
update public.content_exercises set hints = '["Each node in a singly linked list points to the following node.", "The line below sets `head.next`, so name the property to match."]'::jsonb where id = 'ex-ds-linked-list';
update public.content_exercises set hints = '["You only care about distinct values, not how many times each appears.", "Convert the list to the built-in collection that drops duplicates."]'::jsonb where id = 'ex-ds-set';
update public.content_exercises set hints = '["A heap needs its own push function to stay ordered.", "The `heapq` function that adds an item; it pairs with `heappop`."]'::jsonb where id = 'ex-ds-heap';
update public.content_exercises set hints = '["Arrays have a method that exchanges two elements by index.", "Its name says \"swap\" and \"at\" two positions."]'::jsonb where id = 'ex-alg-swap';
update public.content_exercises set hints = '["You''re checking whether the complement was already seen.", "Python''s membership operator tests whether a key is in a dict."]'::jsonb where id = 'ex-alg-two-sum';
update public.content_exercises set hints = '["Memoization stores each result the first time it''s computed.", "`functools` has a decorator (Python 3.9+) that caches every call''s result."]'::jsonb where id = 'ex-alg-memo';
update public.content_exercises set hints = '["A lock allows one thread at a time; you want a counter that allows three.", "The `threading` class that keeps N permits."]'::jsonb where id = 'ex-os-semaphore';
update public.content_exercises set hints = '["`os.environ` behaves like a dict.", "Use the dict method that takes a default for a missing key."]'::jsonb where id = 'ex-os-env';
update public.content_exercises set hints = '["The rows you need come from two tables matched on `customer_id`.", "The keyword that combines tables using the `ON` condition."]'::jsonb where id = 'ex-db-join';
update public.content_exercises set hints = '["`Shape` can''t compute an area itself; subclasses must.", "A class with an abstract method must itself be marked with the same keyword."]'::jsonb where id = 'ex-oop-abstract';
update public.content_exercises set hints = '["`JSONDecoder` turns `Data` into a `Decodable` type.", "Call its method that takes the type and the data."]'::jsonb where id = 'ex-net-json-decode';
update public.content_exercises set hints = '["`json` can parse a string or a file.", "Use the function for a string: it ends in \"s\"."]'::jsonb where id = 'ex-net-json-loads';
update public.content_exercises set hints = '["Each pattern in a Swift `switch` starts with the same keyword.", "Write the keyword that begins a branch, as in the `.success` line above it."]'::jsonb where id = 'ex-swift-switch-result';
update public.content_exercises set hints = '["Python formats `{name}` in a string only when it''s a formatted string literal.", "Put a single-letter prefix right before the opening quote."]'::jsonb where id = 'ex-python-fstring';
update public.content_exercises set hints = '["`try` needs a handler for the error that `int()` raises.", "Python''s keyword for catching an exception type."]'::jsonb where id = 'ex-python-except';
end $codeyhints$;
